using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "GlimmeringBreezeEffect", menuName = "Data/Battle/Effects/Austra/GlimmeringBreeze Effect")]
public class GlimmeringBreezeEffect : LoseEffectEndOfTurnEffect
{
	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<UnitEffects>().DecreaseEffect(effect, effectAmount);
		return 0;
	}
}
